/**
 * Shared formatting utilities for DocNet pages.
 *
 * Centralises relative-time formatting so every widget uses the same i18n keys
 * (`just_now`, `minutes_ago`, `hours_ago`, `days_ago`) instead of hardcoded English strings.
 */

/**
 * Format a date string as relative time ("just now", "5 minutes ago") using i18n,
 * or as absolute date for older entries.
 *
 * @param dateStr   ISO date string
 * @param t         i18n translation function (`$t`)
 * @param formatDate  optional callback to format dates per user preference (e.g. from dateMixin).
 *                    When omitted, falls back to `Date.toLocaleDateString()`.
 */
export function formatRelativeTime(
  dateStr: string,
  t: (key: string, params?: Record<string, any>) => string,
  formatDate?: (d: string) => string,
): string {
  if (!dateStr) return '';
  const date = new Date(dateStr);
  if (isNaN(date.getTime())) return '';

  const diffMs = Date.now() - date.getTime();
  const mins = Math.floor(diffMs / 60000);

  if (mins < 1) return t('just_now');
  if (mins < 60) return t('minutes_ago', { n: mins });

  const hours = Math.floor(mins / 60);
  if (hours < 24) return t('hours_ago', { n: hours });

  const days = Math.floor(hours / 24);
  if (days < 7) return t('days_ago', { n: days });

  // Older than a week: use the caller's date formatter or a sensible default
  if (formatDate) return formatDate(dateStr);
  return date.toLocaleDateString();
}

/**
 * Format a snake_case or kebab-case tool name into a readable Title Case label.
 * e.g. "create_child_issue" → "Create Child Issue"
 */
export function formatToolName(name: string | null | undefined): string {
  if (!name) return '';
  return name
    .replace(/[-_]/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * Check whether an agent has any MCP tool configuration (new mcp_servers or legacy mcp_tools).
 */
export function hasMcpConfig(agent: { mcp_servers?: Record<string, string[]>; mcp_tools?: string[] } | null): boolean {
  if (!agent) return false;
  if (agent.mcp_servers && Object.keys(agent.mcp_servers).length) return true;
  return !!(agent.mcp_tools?.length);
}

/**
 * Count total MCP tools configured on an agent across all servers.
 */
export function mcpToolCount(agent: { mcp_servers?: Record<string, string[]>; mcp_tools?: string[] } | null): number {
  if (!agent) return 0;
  if (agent.mcp_servers && Object.keys(agent.mcp_servers).length) {
    return (Object.values(agent.mcp_servers) as string[][]).reduce((sum, tools) => sum + tools.length, 0);
  }
  return agent.mcp_tools?.length || 0;
}

/**
 * Count every tool available to the agent — native FunctionTools from
 * ``agent.tools`` plus MCP tools from either ``mcp_servers`` (grouped
 * form) or ``mcp_tools`` (legacy flat form). The detail-page header
 * needs this total; ``mcpToolCount`` alone undercounts agents that
 * rely on native tools (e.g. the Document Processor).
 */
export function agentToolCount(
  agent: {
    tools?: string[];
    mcp_servers?: Record<string, string[]>;
    mcp_tools?: string[];
  } | null,
): number {
  if (!agent) return 0;
  const native = agent.tools?.length || 0;
  return native + mcpToolCount(agent);
}

/**
 * Display label for a mission's canonical ``source`` value.
 *
 * The backend column holds lowercase tokens like ``email`` or
 * ``mission_control``. This helper turns them into the human-friendly
 * label shown in list badges, breadcrumbs, and dialogs. Unknown tokens
 * get Title-Cased so a new source added server-side doesn't vanish in
 * the UI before the mapping catches up.
 */
export function formatMissionSource(
  mission: { source?: string } | null | undefined,
  $t?: (key: string) => string,
): string {
  if (!mission) return '';

  // ``unknown`` is the server-side fallback for un-tagged rows —
  // render as empty (no badge) rather than a misleading label.
  // Special-cased here so the i18n path doesn't try to translate
  // an empty string.
  const src = mission.source;
  if (!src || src === 'unknown') return '';

  // Translation path: ``$t('source_email')`` etc.  Looks up the
  // ``source_<token>`` key in the locale table; falls back to
  // the English label if Tolgee returns the key unchanged
  // (locale not yet translated).  Same convention used by
  // ``StatusBadge`` and ``IssueCard.assigneeStatus`` for the
  // ``status_<name>`` family — pinning these via ``$t`` was
  // the production fix for "page is German but the source
  // badge stays English" reports.
  if ($t) {
    const key = `source_${src}`;
    const translated = $t(key);
    if (translated && translated !== key) return translated;
    // Fall through to the English map below if the key is
    // missing — better to render "Email" than "source_email".
  }

  const KNOWN: Record<string, string> = {
    email: 'Email',
    mission_control: 'Mission Control',
    discord: 'Discord',
    slack: 'Slack',
    teams: 'Teams',
    api: 'API',
    agent: 'Agent',
  };
  if (Object.prototype.hasOwnProperty.call(KNOWN, src)) {
    return KNOWN[src];
  }
  // Unseen future source (not yet in KNOWN). Title-Case the token so
  // a new backend value doesn't vanish before the frontend catches up.
  return src.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

